    // to leave room for common item sizes.
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that is too small for most items (below 10)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // Reward the "Best-Fit" logic by targeting specific remainder thresholds
    // If the post_residual is a multiple of 20, it's more likely to accommodate future items
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // Lookahead logic: if the next item is large, prioritize bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalize creating a bin that cannot fit the next item if it's a large one
            if next_item_size > 60 {
                score += 30.0;
            }
        }
    }

    // If this is the only bin that can fit the item, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Discourage opening new bins unless the current options are very poor
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very tight
