pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for leaving small, unusable gaps (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead: penalize if the next item cannot fit in the post_residual space
    if next_item_size > 0 && next_item_size > post_residual {
        score += 25.0;
    }

    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already quite tight
        // or if we have very few open bins (avoiding fragmentation early on)
        score += 15.0 + (mean_residual * 0.5) - (open_bins_count as f64 * 0.2);
    } else {
        // Reward bins that have residuals close to the mean to reduce variance
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Dynamic horizon: as we approach the end of the stream, prioritize aggressive packing
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    // Penalty for being the only bin that fits the item (force reuse)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. Lower is better.
    // 1. Base cost is the post_residual (Best Fit logic: prefer bins where the item fits tightly).
    let mut score = post_residual as f64;

    // 2. Penalize creating "dead space" (small residuals that are hard to fill).
    // Residuals between 1 and 9 are extremely difficult to fill given the input range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration:
    // If we have a next item, check if it fits in the current post_residual.
    // If it fits, we reward this bin heavily to facilitate potential future packing.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Global state adjustment:
    // If we are late in the stream, favor filling existing bins aggressively to close them out.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 5. New bin logic:
    // If this is a new bin (bin_residual == bin_capacity), calculate the "cost" of opening it.
    // We only open a new bin if the existing bins are all "bad" (i.e., would result in high post_residuals).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early, but reduce penalty as we struggle to fit items.
        score += 65.0 - (open_bins_count as f64 * 0.5);
    }

    // 6. Avoid fragmentation:
    // If this is the only bin that can fit the item, prioritize it to avoid wasting space elsewhere.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 7. Balance towards mean:
    // If the post_residual is significantly higher than the mean, penalize it to encourage
    // tighter packing across all bins.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // We favor bins where post_residual is as small as possible.

    // 2. Lookahead Coupling:
    // If post_residual is close to next_item_size, we favor this bin to enable future packing.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 3. Fragmentation Penalty:
    // If post_residual is small but > 0, it creates "dead space" that cannot fit typical items.
    // We penalize very small residuals (1..9) unless the bin is completely full (0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean Residual Balancing:
    // Discourage bins that deviate significantly from the average state of open bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. New Bin Thresholding:
    // If this is a new bin (residual == capacity), apply a threshold cost based on how many
    // open bins are currently available. Only open a new bin if the "fit" in existing ones
    // is truly poor (high score).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage filling existing ones.
        // We reduce this penalty if we have very few open bins or if many items remain.
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 - (open_bins_count as f64 * 0.5) + (progress * 10.0);
    }

    // 6. Urgency factor:
    // If this is the last chance to fit the item in an existing bin, reduce the score
    // to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses
    // to force tighter packing later on.
    let dead_space_penalty = (1.0 - (post / bin_capacity as f64)).powf(2.0) * (1.0 + progress);

    // Reward bins that keep the post_residual close to the global mean_residual
    // to maintain a consistent distribution of bin states.
    let deviation_from_mean = (post - mean_residual).abs();

    // Lookahead: if the next item is large, penalize small residuals that would 
    // force an early new bin later.
    let lookahead_pressure = if next_item_size > 0 {
        (next_item_size as f64 / (post + 1.0)).powf(1.5)
    } else {
        0.0
    };

    // New bin candidate logic:
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    let mut score = if bin_residual == bin_capacity {
        // Base cost for opening a new bin increases as we approach the end of the stream
        // to discourage wasting capacity on nearly empty bins.
        15.0 + (progress * 20.0)
    } else {
        post + (dead_space_penalty * 10.0) + (deviation_from_mean * 0.5) + (lookahead_pressure * 5.0)
    };

    // If this is the only bin that can fit the item, give it a strong preference
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (dead space between 1 and 9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead: If next_item_size fits perfectly into the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = post_residual - next_item_size;
        // Reward configurations that leave exactly 0 or very little space for the next item
        score -= (100.0 - fit_gap as f64) * 0.8;
    }

    // 3. Global awareness: If this is the last fitting bin, penalize it to force usage of other bins first
    // unless the fit is extremely tight (Best Fit behavior).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 20.0;
    }

    // 4. Mean-residual balancing: Avoid opening new bins if the current bin's post_residual 
    // is significantly better than the global average.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: higher if many open bins have high capacity left
        score += mean_residual * 0.5;
        // Moderate penalty for opening new bins early in the stream
        score += (1.0 - (step_index as f64 / total_items as f64)) * 10.0;
    } else {
        // Reward bins that align with the mean residual to keep distribution uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Heavily penalize large post_residuals (wasted space)
    // We prioritize bins where the item fits tightly.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic:
    // If post_residual is small but not zero, it creates "unusable" gaps.
    // Penalize gaps that are smaller than the smallest possible incoming items (e.g., < 10)
    // unless the gap is exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Synergy (Harmonic coupling with next_item_size):
    // If we have a next item, try to leave a residual that fits it perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize bins that leave no room for the next item if it could have fit elsewhere
            score += 25.0;
        }
    }

    // 4. Thresholding for new bins:
    // Only open a new bin if the current fit is extremely inefficient (high post_residual).
    // If bin_residual == bin_capacity, we are evaluating the "New Bin" option.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high to encourage filling existing ones.
        score = 65.0;

        // If we have many open bins that are nearly full, don't open a new one.
        if mean_residual < 20.0 {
            score += 40.0;
        }
    }

    // 5. Fitting constraint:
    // If this is the last bin that can fit the item (fitting_bins_count == 1),
    // strongly prefer this bin to avoid creating a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progressive scaling:
    // As the stream nears the end, become more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
